<?php
declare(strict_types=1);
function admin_shell(array $db,string $title,string $content,string $active): void {
    $me=user($db);
    $nav=[['/admin','Обзор','grid'],['/admin/articles','Статьи','file'],['/admin/articles/new','Новая статья','plus'],['/admin/media','Изображения','image']];
    if(can_admin($me)){$nav[]=['/admin/categories','Категории','book'];$nav[]=['/admin/feedback','Отзывы','heart'];$nav[]=['/admin/settings','Настройки','settings'];}
    if(is_owner($me)){$nav[]=['/admin/users','Редакторы','users'];}
    ob_start();?><div class="container admin-layout"><aside class="admin-sidebar"><div class="admin-side-head"><span class="section-eyebrow">CONTROL PANEL</span><h3>Управление Wiki</h3><small><?=e($me['login'])?> · <?=e($me['role'])?></small></div><nav aria-label="Панель управления"><?php foreach($nav as [$link,$name,$ico]):?><a href="<?=e($link)?>" class="<?=$active===$link?'active':''?>"><?=icon($ico,19)?> <?=e($name)?></a><?php endforeach;?></nav><div class="admin-side-foot"><a href="/" target="_blank"><?=icon('external',16)?> Открыть Wiki</a><form method="post" action="/logout"><?=csrf_field()?><button type="submit"><?=icon('log-out',16)?> Выйти</button></form></div></aside><div class="admin-main"><div class="admin-title"><div><span class="section-eyebrow">VOSTERA / WIKI STUDIO</span><h1><?=e($title)?></h1></div><a class="admin-view" href="/" target="_blank"><?=icon('external',16)?> Посмотреть Wiki</a></div><?=$content?></div></div><?php render_layout($db,$title,ob_get_clean()); }
function view_admin_home(array $db): void {
    $items=$db['articles'];$pub=count(array_filter($items,fn($a)=>$a['status']==='published'));$draft=count($items)-$pub;$yes=0;$no=0;foreach($db['votes'] as $v){if($v==='yes')$yes++;else $no++;}
    $last=$items;usort($last,fn($a,$b)=>strcmp($b['updated_at'],$a['updated_at']));$last=array_slice($last,0,7);
    ob_start();?><div class="admin-stats"><div><span><?=icon('file',24)?></span><strong><?=count($items)?></strong><small>Всего материалов</small></div><div><span><?=icon('check',24)?></span><strong><?=$pub?></strong><small>Опубликовано</small></div><div><span><?=icon('edit',24)?></span><strong><?=$draft?></strong><small>Черновики</small></div><div><span><?=icon('heart',24)?></span><strong><?=$yes+$no?></strong><small>Получено оценок</small></div></div><div class="admin-split"><section class="admin-panel"><div class="admin-panel-head"><h2>Последние материалы</h2><a href="/admin/articles">Все статьи <?=icon('arrow',15)?></a></div><table class="data-table"><thead><tr><th>Название</th><th>Статус</th><th>Изменено</th></tr></thead><tbody><?php foreach($last as $a):?><tr><td><a href="/admin/articles/edit/<?=$a['id']?>"><?=e($a['title'])?></a></td><td><span class="status <?=$a['status']==='published'?'status-published':''?>"><?= $a['status']==='published'?'На сайте':'Черновик' ?></span></td><td><?=e(to_date($a['updated_at']))?></td></tr><?php endforeach;?></tbody></table></section><section class="admin-panel admin-quick"><h2>Быстрые действия</h2><p>Добавляйте инструкции, проверяйте обратную связь и поддерживайте материалы в актуальном состоянии.</p><a class="btn btn-primary" href="/admin/articles/new"><?=icon('plus',18)?> Создать статью</a><a class="admin-quick-link" href="/admin/media"><?=icon('image',18)?> Загрузить изображение <?=icon('chevron',16)?></a><a class="admin-quick-link" href="/admin/articles"><?=icon('file',18)?> Управление публикациями <?=icon('chevron',16)?></a></section></div><?php admin_shell($db,'Обзор',ob_get_clean(),'/admin'); }
function view_admin_articles(array $db): void {
    $articles=$db['articles'];usort($articles,fn($a,$b)=>strcmp($b['updated_at'],$a['updated_at']));
    ob_start();?><div class="admin-toolbar"><p>Публикуйте новые материалы, корректируйте существующие и сохраняйте черновики.</p><a href="/admin/articles/new" class="btn btn-primary"><?=icon('plus',17)?> Новая статья</a></div><section class="admin-panel"><table class="data-table"><thead><tr><th>Название и раздел</th><th>Статус</th><th>Дата</th><th>Действие</th></tr></thead><tbody><?php foreach($articles as $a):$c=category_for($db,$a['category_id']);?><tr><td><strong><?=e($a['title'])?></strong><small><?=e($c['name']??'Без категории')?></small></td><td><span class="status <?=$a['status']==='published'?'status-published':''?>"><?=$a['status']==='published'?'На сайте':'Черновик'?></span></td><td><?=e(to_date($a['updated_at']))?></td><td><a class="table-action" href="/admin/articles/edit/<?=$a['id']?>">Изменить <?=icon('arrow',14)?></a></td></tr><?php endforeach;?></tbody></table></section><?php admin_shell($db,'Статьи',ob_get_clean(),'/admin/articles'); }
function view_admin_edit(array $db,?array $a): void {
    $new=$a===null;$me=user($db);
    $a??=['id'=>0,'title'=>'','slug'=>'','excerpt'=>'','keywords'=>'','body'=>"# Заголовок\n\nНапишите инструкцию здесь.\n\n## Первый шаг\n\n- Полезный совет\n",'category_id'=>$db['categories'][0]['id'],'featured'=>false,'status'=>'draft'];
    ob_start();?><form method="post" action="/admin/article/save" id="editorForm" class="editor-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$a['id']?>"><div class="admin-toolbar"><p><?= $new?'Создание нового материала':'Изменение статьи #'.(int)$a['id'] ?></p><div class="editor-actions"><a href="/admin/articles" class="btn btn-ghost">Отмена</a><button class="btn btn-primary" type="submit"><?=icon('check',17)?> Сохранить</button></div></div><div class="editor-columns"><section class="admin-panel editor-panel"><label>Заголовок статьи<input required type="text" name="title" value="<?=e($a['title'])?>" maxlength="140" placeholder="Например: Как начать играть"></label><label>URL-адрес (латиницей)<input type="text" name="slug" value="<?=e($a['slug'])?>" maxlength="90" placeholder="Создастся из заголовка автоматически"><small>Допустимы латинские буквы, цифры и дефис. Если оставить пустым, адрес сформируется из названия.</small></label><label>Краткое описание<textarea required name="excerpt" maxlength="260" rows="2" placeholder="Описание для карточек и поиска"><?=e($a['excerpt'])?></textarea></label><label>Содержимое <small>Markdown</small><div class="editor-tools"><button type="button" data-insert="bold" title="Жирный">B</button><button type="button" data-insert="heading" title="Заголовок">H2</button><button type="button" data-insert="list" title="Список">☷</button><button type="button" data-insert="link" title="Ссылка">↗</button><button type="button" data-insert="quote" title="Примечание">“</button></div><textarea id="articleEditor" required name="body" rows="23" maxlength="40000" spellcheck="true"><?=e($a['body'])?></textarea></label><p class="editor-hint">Поддерживаются заголовки # и ##, **жирный текст**, ссылки [название](https://...), списки, цитаты через &gt;, изображения ![описание](/uploads/файл.png).</p><div class="preview-toolbar"><button type="button" class="btn btn-ghost" data-preview-button><?=icon('book',16)?> Предпросмотр статьи</button></div><div class="editor-preview article-content" id="articlePreview" hidden></div></section><aside class="editor-aside"><section class="admin-panel"><h3>Настройки публикации</h3><label>Категория<select name="category_id" required><?php foreach($db['categories'] as $cat):?><option value="<?=$cat['id']?>" <?=$cat['id']===$a['category_id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></label><label>Статус<select name="status"><option value="draft" <?=$a['status']==='draft'?'selected':''?>>Черновик</option><option value="published" <?=$a['status']==='published'?'selected':''?>>Опубликована</option></select></label><label>Поисковые слова<input type="text" maxlength="300" name="keywords" value="<?=e($a['keywords']??'')?>" placeholder="вход, логин, авторизация"></label><label class="check-row"><input type="checkbox" name="featured" value="1" <?=$a['featured']?'checked':''?>> Рекомендуемая на главной</label></section><?php if(!$new):?><section class="admin-panel"><h3>Ссылка на статью</h3><a class="table-action" target="_blank" href="<?=e(article_path($a))?>"><?=e(article_path($a))?> <?=icon('external',15)?></a><?php if(can_admin($me)):?><form></form><div class="danger-zone"><button type="submit" form="deleteArticleForm" class="btn btn-danger" data-confirm="Удалить эту статью без возможности восстановления?">Удалить статью</button></div><?php endif;?></section><?php endif;?><section class="admin-panel"><h3>Работа с изображениями</h3><p class="admin-muted">Загрузите изображение и скопируйте Markdown-код в редактор.</p><a class="table-action" href="/admin/media">Открыть медиатеку <?=icon('arrow',16)?></a></section></aside></div></form><?php if(!$new && can_admin($me)):?><form method="post" id="deleteArticleForm" action="/admin/article/delete" class="hidden-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$a['id']?>"></form><?php endif;?><?php admin_shell($db,$new?'Новая статья':'Редактировать статью',ob_get_clean(),'/admin/articles'); }
function view_admin_categories(array $db): void {
    $categories=$db['categories'];usort($categories,fn($a,$b)=>$a['sort']<=>$b['sort']);
    ob_start();?><p class="admin-muted">Редактирование разделов доступно администраторам. Раздел с опубликованными статьями нельзя удалить до их переноса.</p><div class="admin-split"><section class="admin-panel"><h2>Разделы Wiki</h2><?php foreach($categories as $c):?><details class="category-edit"><summary><?=icon($c['icon'],20)?> <strong><?=e($c['name'])?></strong><span><?=count(published($db,$c['id']))?> статей · ID <?=$c['id']?></span></summary><form method="post" action="/admin/category/save" class="form-stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><label>Название<input required name="name" value="<?=e($c['name'])?>" maxlength="90"></label><label>Адрес<input name="slug" value="<?=e($c['slug'])?>" maxlength="90"></label><label>Описание<textarea name="description" rows="2" maxlength="240"><?=e($c['description'])?></textarea></label><div class="form-row"><label>Иконка<select name="icon"><?php foreach(['rocket','gamepad','shield','wrench','messages','wallet','bell','book'] as $ic):?><option value="<?=$ic?>" <?=$ic===$c['icon']?'selected':''?>><?=$ic?></option><?php endforeach;?></select></label><label>Порядок<input type="number" name="sort" value="<?=$c['sort']?>" min="1" max="999"></label></div><button class="btn btn-primary" type="submit">Сохранить категорию</button></form><form method="post" action="/admin/category/delete" class="delete-category"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button type="submit" class="btn btn-danger" data-confirm="Удалить пустую категорию?">Удалить категорию</button></form></details><?php endforeach;?></section><section class="admin-panel"><h2>Новый раздел</h2><form method="post" action="/admin/category/save" class="form-stack"><?=csrf_field()?><label>Название<input required name="name" maxlength="90" placeholder="Например: Вопросы игроков"></label><label>URL-адрес<input name="slug" maxlength="90" placeholder="voprosy-igrokov"></label><label>Описание<textarea name="description" rows="3" maxlength="240"></textarea></label><div class="form-row"><label>Иконка<select name="icon"><?php foreach(['book','rocket','gamepad','shield','wrench','messages','wallet','bell'] as $ic):?><option value="<?=$ic?>"><?=$ic?></option><?php endforeach;?></select></label><label>Порядок<input name="sort" type="number" min="1" max="999" value="10"></label></div><button type="submit" class="btn btn-primary"><?=icon('plus',17)?> Создать раздел</button></form></section></div><?php admin_shell($db,'Категории',ob_get_clean(),'/admin/categories'); }
function view_admin_settings(array $db): void {
    ob_start();?><section class="admin-panel settings-panel"><p class="admin-muted">Укажите настоящие адреса ресурсов проекта. Пустые ссылки не показываются посетителям.</p><form method="post" action="/admin/settings" class="form-stack"><?=csrf_field()?><label>Текст в шапке Wiki<input name="hero_notice" maxlength="220" value="<?=e(setting($db,'hero_notice'))?>"></label><label>Объявление на главной<textarea name="announcement" rows="3" maxlength="500"><?=e(setting($db,'announcement'))?></textarea></label><label>URL игрового сайта<input name="site_url" type="url" placeholder="https://vostera.example" value="<?=e(setting($db,'site_url'))?>"></label><label>URL форума<input name="forum_url" type="url" placeholder="https://forum.vostera.example" value="<?=e(setting($db,'forum_url'))?>"></label><label>Ссылка на официальный клиент<input name="download_url" type="url" placeholder="https://..." value="<?=e(setting($db,'download_url'))?>"></label><button type="submit" class="btn btn-primary">Сохранить настройки <?=icon('check',17)?></button></form></section><?php admin_shell($db,'Настройки',ob_get_clean(),'/admin/settings'); }
function view_admin_media(array $db): void {
    $media=array_reverse($db['media']??[]);
    ob_start();?><div class="admin-split"><section class="admin-panel"><h2>Загрузка изображения</h2><p class="admin-muted">PNG, JPG или WEBP. Максимум <?=round((cfg()['upload_max_bytes']??3145728)/1048576,1)?> МБ. Файлы других типов запрещены.</p><form method="post" enctype="multipart/form-data" action="/admin/media" class="form-stack"><?=csrf_field()?><label>Выберите файл<input name="image" type="file" accept="image/png,image/jpeg,image/webp" required></label><label>Описание для статьи<input type="text" name="alt" maxlength="110" placeholder="Что изображено на картинке"></label><button type="submit" class="btn btn-primary"><?=icon('image',18)?> Загрузить</button></form></section><section class="admin-panel"><h2>Медиатека</h2><?php if(!$media):?><p class="admin-muted">Здесь появятся загруженные файлы.</p><?php else:?><div class="media-grid"><?php foreach($media as $m):$markdown='!['.($m['alt']?:'Изображение').']('.$m['url'].')';?><div class="media-item"><img src="<?=e($m['url'])?>" alt="<?=e($m['alt'])?>" loading="lazy"><button type="button" data-copy-text="<?=e($markdown)?>" class="media-copy"><?=icon('copy',15)?> Копировать код</button></div><?php endforeach;?></div><?php endif;?></section></div><?php admin_shell($db,'Медиатека',ob_get_clean(),'/admin/media'); }
function view_admin_feedback(array $db): void {
    $aStats=[];foreach($db['votes'] as $key=>$v){$id=(int)explode(':',$key)[0];$aStats[$id][$v]=($aStats[$id][$v]??0)+1;}
    $rows=array_filter($db['articles'],fn($a)=>isset($aStats[$a['id']]));usort($rows,fn($a,$b)=>array_sum($aStats[$b['id']])<=>array_sum($aStats[$a['id']]));
    ob_start();?><section class="admin-panel"><h2>Полезность статей</h2><p class="admin-muted">Анонимные оценки «Да» и «Нет» помогают находить инструкции, нуждающиеся в доработке.</p><table class="data-table"><thead><tr><th>Статья</th><th>Полезно</th><th>Не помогло</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><a href="/admin/articles/edit/<?=$a['id']?>"><?=e($a['title'])?></a></td><td><?=($aStats[$a['id']]['yes']??0)?></td><td><?=($aStats[$a['id']]['no']??0)?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="admin-muted">Оценок пока нет.</p><?php endif;?></section><?php admin_shell($db,'Отзывы',ob_get_clean(),'/admin/feedback'); }
function view_admin_users(array $db): void {
    ob_start();?><div class="admin-split"><section class="admin-panel"><h2>Сотрудники</h2><?php foreach($db['users'] as $u):?><div class="user-row"><div><strong><?=e($u['login'])?></strong><small><?=e($u['role'])?> · <?=$u['active']?'Активен':'Заблокирован'?></small></div><?php if($u['role']!=='owner'):?><details><summary>Изменить</summary><form method="post" action="/admin/user/update" class="form-stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><label>Роль<select name="role"><option value="editor" <?=$u['role']==='editor'?'selected':''?>>Редактор</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Администратор</option></select></label><label>Новый пароль (оставить пустым, если не менять)<input type="password" name="password" minlength="12" autocomplete="new-password"></label><label class="check-row"><input type="checkbox" name="active" value="1" <?=$u['active']?'checked':''?>> Активный доступ</label><button class="btn btn-primary" type="submit">Сохранить</button></form></details><?php endif;?></div><?php endforeach;?></section><section class="admin-panel"><h2>Создать сотрудника</h2><form method="post" action="/admin/user/create" class="form-stack"><?=csrf_field()?><label>Логин<input name="login" required pattern="[A-Za-z0-9_]{3,40}" maxlength="40" minlength="3"></label><label>Пароль (не меньше 12 символов)<input type="password" name="password" autocomplete="new-password" required minlength="12"></label><label>Роль<select name="role"><option value="editor">Редактор: статьи и медиа</option><option value="admin">Администратор: разделы и настройки</option></select></label><button class="btn btn-primary" type="submit">Добавить пользователя</button></form></section></div><?php admin_shell($db,'Редакторы',ob_get_clean(),'/admin/users'); }
